-- COMPROBACIÓN: renglones con código que NO está en ningún maestro (debe salir vacío)
select s->>'titulo' as seccion, f->>'concepto' as renglon, f->>'codigo' as codigo
  from public.carnaval_existencias e,
       jsonb_array_elements(e.secciones) s,
       jsonb_array_elements(s->'filas') f
 where e.fecha = date '2026-10-28'
   and coalesce(f->>'codigo', '') not in ('', '-')
   and not exists (select 1 from public.productos p where p.sku = f->>'codigo')
   and not exists (select 1 from public.pasivos_maestro m where m.codigo = f->>'codigo')
   and not exists (select 1 from public.carnaval_productos c where c.codigo = f->>'codigo');
